<script lang="ts">import { goto } from '$app/navigation';import { GraduationCap } from 'lucide-svelte';import { register } from '../../../features/auth/api/authApi';let name=$state('');let email=$state('');let password=$state('');let error=$state('');let loading=$state(false);async function submit(e:SubmitEvent){e.preventDefault();error='';loading=true;try{await register(name,email,password);await goto('/auth/login');}catch(e){error=e instanceof Error?e.message:'Pendaftaran gagal';}finally{loading=false;}}</script><main class="auth-page"><form class="auth-card" onsubmit={submit}><a class="brand" href="/"><GraduationCap/> Delcom <b>Courses</b></a><h1>Buat akun baru</h1><p>Bergabung dan mulai belajar hari ini.</p>{#if error}<div class="alert">{error}</div>{/if}<label>Nama lengkap<input bind:value={name} required autocomplete="name"/></label><label>Email<input type="email" bind:value={email} required autocomplete="email"/></label><label>Password<input type="password" bind:value={password} required minlength="6" autocomplete="new-password"/></label><button class="primary full" disabled={loading}>{loading?'Memproses...':'Daftar'}</button><p class="auth-foot">Sudah punya akun? <a href="/auth/login">Masuk</a></p></form></main>